            String[] p = sc.nextLine().trim().split("\\s+");
            if (p[0].equals("END")) {
                break;
            }
            if (p[0].equals("D")) {
                System.out.println(acc.deposit(Long.parseLong(p[1])) ? "Deposited " + p[1] : "Invalid amount");
