// A student knows its own marks, so it can compute its own average and grade.
public class Student {
    private final String name;
    private final double m1;
    private final double m2;
    private final double m3;

    public Student(String name, double m1, double m2, double m3) {
        this.name = name;
        this.m1 = m1;
        this.m2 = m2;
        this.m3 = m3;
    }

    public String getName() {
        return name;
    }

    public double average() {
        return (m1 + m2 + m3) / 3;
    }

    public String grade() {
        double a = average();
        if (a >= 8.5) {
            return "A";
        } else if (a >= 7.0) {
            return "B";
        } else if (a >= 5.5) {
            return "C";
        } else if (a >= 4.0) {
            return "D";
        }
        return "F";
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Student[] list = new Student[n];
        for (int i = 0; i < n; i++) {
            String[] p = sc.nextLine().split(";");
            list[i] = new Student(p[0].trim(), Double.parseDouble(p[1].trim()), Double.parseDouble(p[2].trim()),
                    Double.parseDouble(p[3].trim()));
        }
        Student best = null;
        for (Student s : list) {
            System.out.println(String.format("%-12s %5.2f %s", s.getName(), s.average(), s.grade()));
            if (best == null || s.average() > best.average()) {
                best = s;
            }
        }
        if (best != null) {
            System.out.println(String.format("Best: %s (%.2f)", best.getName(), best.average()));
        }
    }
}

#!/usr/bin/env node
// CuongThai Code Lab · PRO192 (Java OOP) — LOCAL GRADER · MÁY CHẤM CHẠY TRÊN MÁY BẠN
// Exercise / Bài: pro192-1-1-students — Procedural vs OO: a student report
//
